-- Clean-slate reseed of the firework effect catalogue.
-- Generated from platform/lib/fireworks/effect-catalogue.ts by
-- scripts/seed/generate-firework-catalogue-migration.mjs. Re-run the
-- generator after editing the catalogue to refresh this file.
--
-- Upserts the calibrated set (24 effects,
-- 72 coloured firework variants) tuned to the Brocade
-- reference bar, re-maps dependent catalogue_items and multishot_fireworks that
-- still point at catalogue or legacy-migrated fireworks to the nearest
-- catalogue effect's default firework so existing show timelines keep
-- rendering. Manual, video-inferred, and LLM-generated fireworks are preserved.
-- Legacy catalogue effects and fireworks not in the catalogue are pruned after
-- those legacy dependents are re-linked.
-- retained style-default links and editor versions stay attached to their
-- upserted ids.

-- Map old effect slugs to target catalogue effect slugs. Catalogue slugs
-- map to themselves; known legacy slugs remap to the nearest catalogue
-- effect; anything unmapped falls back to 'peony'.
create temp table if not exists _effect_remap (old_slug text, target_slug text);
insert into _effect_remap (old_slug, target_slug)
  select * from (values
    ('peony', 'peony'),
    ('chrysanthemum', 'chrysanthemum'),
    ('brocade', 'brocade'),
    ('kamuro', 'kamuro'),
    ('willow', 'willow'),
    ('palm', 'palm'),
    ('ring', 'ring'),
    ('saturn', 'saturn'),
    ('crossette', 'crossette'),
    ('double_break', 'double_break'),
    ('bowtie', 'bowtie'),
    ('horsetail', 'horsetail'),
    ('comet', 'comet'),
    ('mine', 'mine'),
    ('pearls', 'pearls'),
    ('pistil', 'pistil'),
    ('nishiki', 'nishiki'),
    ('strobe', 'strobe'),
    ('crackle', 'crackle'),
    ('silverFish', 'silverFish'),
    ('waterfall', 'waterfall'),
    ('whirl', 'whirl'),
    ('roman_candle', 'roman_candle'),
    ('fountain', 'fountain')
  ) as v(old_slug, target_slug);
insert into _effect_remap (old_slug, target_slug) values
  ('silver-fish', 'silverFish'),
  ('tail', 'comet'),
  ('custom-star-mqjgvfgo', 'peony'),
  ('legacy-effect-spec', 'peony');

-- Capture dependent -> target catalogue effect slug before reseed.
create temp table if not exists _dep_effect_targets (src text, dep_id uuid, target_effect_slug text);
insert into _dep_effect_targets (src, dep_id, target_effect_slug)
  select 'catalogue_item'::text, ci.id, coalesce(r.target_slug, 'peony')
  from public.catalogue_items ci
  join public.fireworks fw on ci.firework_id = fw.id
  join public.firework_effects fe on fe.id = fw.firework_effect_id
  left join _effect_remap r on r.old_slug = fe.slug
  where ci.firework_id is not null
    and fw.source in ('catalogue', 'legacy_migrated');
insert into _dep_effect_targets (src, dep_id, target_effect_slug)
  select 'multishot_firework'::text, mf.id, coalesce(r.target_slug, 'peony')
  from public.multishot_fireworks mf
  join public.fireworks fw on mf.firework_id = fw.id
  join public.firework_effects fe on fe.id = fw.firework_effect_id
  left join _effect_remap r on r.old_slug = fe.slug
  where mf.firework_id is not null
    and fw.source in ('catalogue', 'legacy_migrated');

-- Reseed base effects (upsert by slug). multishot_fireworks.firework_id is not
-- null with on-delete restrict, so effects/fireworks are upserted in place and
-- legacy rows are pruned only after dependents are re-linked below.
insert into public.firework_effects
  (slug, name, description, family, pattern_key, model_json, sort_order, source)
values
  ('peony', 'Peony', 'Round radial burst of glowing stars without persistent trails.', 'aerial_burst', 'peony', '{"version":3,"geometry":"sphere","trailProfile":"none","renderDefaults":{"pattern":"fibonacci","geometry":"sphere","trailProfile":"none","size":115,"liftVelocity":17,"shellLife":4.2,"burst":{"speed":[2.4,4],"gravity":[-0.5,0],"life":[2.6,3.8],"flairColorMode":"bombColor"},"flair":{"enabled":false},"crackle":{"enabled":false,"probability":0,"sound":"crackle"},"strobe":{"enabled":false,"frequencyHz":12,"dutyCycle":0.45},"split":{"enabled":false,"fragments":4,"speed":1.55,"delayRatio":0.42},"sound":{"launch":true,"boom":"auto"},"mortar":{"sound":true,"smokeParticles":100},"stars":{"outer":{"enabled":true,"count":80,"burst":{"speed":[2.4,4],"gravity":[-0.5,0],"life":[2.6,3.8],"flairColorMode":"bombColor"},"head":{"visible":true,"size":170,"glowStrength":1,"glowPadding":150,"whiteCoreSizePercent":10,"whiteCoreBlurPercent":15,"coreSoftness":70,"coreBrightness":30,"coreOpacityFalloff":60,"glowSize":90,"glowSoftness":100,"glowOpacityFalloff":100,"glowBlur":45,"backgroundGlowOpacityFalloff":75,"backgroundGlowSoftness":50,"brightnessHoldPercent":40,"brightnessHoldExponent":0.8,"opening":{"colour":{"enabled":true,"color":{"r":1,"g":0.42,"b":0.08},"fadePercent":16},"size":{"enabled":false,"startPercent":35,"growPercent":18}},"closing":{"colour":{"enabled":true,"color":{"r":1,"g":0.84,"b":0.4},"fadePercent":32},"size":{"enabled":true,"endPercent":0,"shrinkPercent":55}}},"colourPattern":{"mode":"solid","axis":"vertical","count":1,"colours":[]},"burstTrail":{"preset":"none","enabled":false,"particlesPerStar":0}},"core":{"enabled":false}}}}'::jsonb, 10, 'reference'),
