  ('brocade', 'Brocade', 'White-gold crown with a hot lift streak, amber burst haze, and long falling brocade trails. The reference quality bar.', 'aerial_burst', 'brocade', '{"version":3,"geometry":"crown","trailProfile":"glitter","renderDefaults":{"pattern":"wave","geometry":"crown","trailProfile":"glitter","size":270,"color":{"r":1,"g":0.82,"b":0.36},"secondaryColor":{"r":1,"g":0.98,"b":0.88},"liftVelocity":12.6,"burst":{"speed":[1.45,2.85],"gravity":[-0.82,-0.34],"life":[1.15,4.95],"flairColorMode":"bombColor"},"trail":{"density":2.85,"length":2.35,"sparkle":0.62,"thickness":0.86},"flair":{"enabled":true},"crackle":{"enabled":false,"probability":0,"sound":"crackle"},"strobe":{"enabled":false,"frequencyHz":12,"dutyCycle":0.45},"split":{"enabled":false,"fragments":4,"speed":1.55,"delayRatio":0.42},"sound":{"launch":true,"boom":"light"},"mortar":{"sound":true,"smokeParticles":70},"brocade":{"streakCount":48,"trailStep":3,"tubeRadius":3.2,"headsEnabled":true,"headSize":900,"glowStrength":1.2,"greenRatio":0.5,"headColors":{"green":{"r":0.4,"g":1,"b":0.5},"red":{"r":1,"g":0.28,"b":0.32}},"palette":{"hot":{"r":1,"g":0.93,"b":0.72},"ember":{"r":1,"g":0.42,"b":0.14}}}}}'::jsonb, 30, 'reference'),
