  ('fountain', 'fountain-azure', 'Fountain Azure', 'Catalogue variant for Fountain Azure.', '#1e7fff', '#7fd0ff', array['#1e7fff', '#7fd0ff', '#f5f7fa']::text[], 6, 60, '{"shellType":"fountain","spreadSize":3,"starLifeMs":1700,"starLifeVariation":0.18,"starDensity":1,"color":"#1e7fff","colorPalette":["#1e7fff","#7fd0ff","#f5f7fa"],"glitter":"light","crackle":false,"strobe":false,"ring":false,"crossette":false,"horsetail":false}'::jsonb, '{}'::jsonb, 'catalogue', 0.75)
) as v(effect_slug, slug, name, description, primary_color, secondary_color, color_palette, duration_seconds, height_meters, variant_json, render_overrides_json, source, confidence)
join public.firework_effects fe on fe.slug = v.effect_slug
on conflict (slug) do update set
  firework_effect_id = excluded.firework_effect_id,
  name = excluded.name,
  description = excluded.description,
  primary_color = excluded.primary_color,
  secondary_color = excluded.secondary_color,
  color_palette = excluded.color_palette,
  duration_seconds = excluded.duration_seconds,
  height_meters = excluded.height_meters,
  variant_json = excluded.variant_json,
  render_overrides_json = excluded.render_overrides_json,
  source = excluded.source,
  confidence = excluded.confidence,
  updated_at = now();

-- Re-link dependents to the new catalogue default firework for each target effect.
update public.catalogue_items ci
  set firework_id = nf.id
  from _dep_effect_targets d
  join public.firework_effects te on te.slug = d.target_effect_slug
  join public.fireworks nf on nf.firework_effect_id = te.id and nf.slug = te.slug || '-default'
  where d.src = 'catalogue_item' and ci.id = d.dep_id;
update public.multishot_fireworks mf
  set firework_id = nf.id
  from _dep_effect_targets d
  join public.firework_effects te on te.slug = d.target_effect_slug
  join public.fireworks nf on nf.firework_effect_id = te.id and nf.slug = te.slug || '-default'
  where d.src = 'multishot_firework' and mf.id = d.dep_id;

-- Prune legacy fireworks no longer in the catalogue. Imported, manually
-- authored, and LLM-generated variants are intentionally preserved.
delete from public.fireworks where slug not in (
  'peony-default', 'peony-crimson', 'peony-azure', 'chrysanthemum-default', 'chrysanthemum-crimson', 'chrysanthemum-azure', 'brocade-default', 'brocade-crimson', 'brocade-azure', 'kamuro-default', 'kamuro-crimson', 'kamuro-azure', 'willow-default', 'willow-crimson', 'willow-azure', 'palm-default', 'palm-crimson', 'palm-azure', 'ring-default', 'ring-crimson', 'ring-azure', 'saturn-default', 'saturn-crimson', 'saturn-azure', 'crossette-default', 'crossette-crimson', 'crossette-azure', 'double_break-default', 'double_break-crimson', 'double_break-azure', 'bowtie-default', 'bowtie-crimson', 'bowtie-azure', 'horsetail-default', 'horsetail-crimson', 'horsetail-azure', 'comet-default', 'comet-crimson', 'comet-azure', 'mine-default', 'mine-crimson', 'mine-azure', 'pearls-default', 'pearls-crimson', 'pearls-azure', 'pistil-default', 'pistil-crimson', 'pistil-azure', 'nishiki-default', 'nishiki-crimson', 'nishiki-azure', 'strobe-default', 'strobe-crimson', 'strobe-azure', 'crackle-default', 'crackle-crimson', 'crackle-azure', 'silverFish-default', 'silverFish-crimson', 'silverFish-azure', 'waterfall-default', 'waterfall-crimson', 'waterfall-azure', 'whirl-default', 'whirl-crimson', 'whirl-azure', 'roman_candle-default', 'roman_candle-crimson', 'roman_candle-azure', 'fountain-default', 'fountain-crimson', 'fountain-azure'
)
and source in ('catalogue', 'legacy_migrated');

-- Prune legacy effects no longer in the catalogue only once no preserved
-- firework still references them.
delete from public.firework_effects where slug not in (
  'peony', 'chrysanthemum', 'brocade', 'kamuro', 'willow', 'palm', 'ring', 'saturn', 'crossette', 'double_break', 'bowtie', 'horsetail', 'comet', 'mine', 'pearls', 'pistil', 'nishiki', 'strobe', 'crackle', 'silverFish', 'waterfall', 'whirl', 'roman_candle', 'fountain'
)
and source in ('reference', 'legacy_migrated')
and not exists (
  select 1
  from public.fireworks fw
  where fw.firework_effect_id = public.firework_effects.id
);

drop table _dep_effect_targets;
drop table _effect_remap;
